  ('plumbing_shutoff_before_repair', 'plumbing', 'worker_safety_advisory', 'warning', 'Nhắc thợ khóa van nước khu vực liên quan, đặt khăn hoặc khay hứng và xác nhận dòng nước đã giảm trước khi tháo nối.', '{"corpus_version":"b3-draft-2026-06-04","signoff_status":"approved","source_refs":["S3"],"source_trust_score":1,"source_trust_scoring":"source_set_minimum_trust_proposal","generated_by":"kael-b3-corpus-to-sql"}'::jsonb, true),
  ('plumbing_leak_near_electric_risk', 'plumbing', 'worker_safety_advisory', 'urgent', 'Nếu nước rò gần ổ cắm, thiết bị điện hoặc dây điện, ưu tiên cách ly khu vực và phối hợp xử lý điện an toàn trước khi sửa nước.', '{"corpus_version":"b3-draft-2026-06-04","signoff_status":"approved","source_refs":["S1","S3","S7"],"source_trust_score":0.95,"source_trust_scoring":"source_set_minimum_trust_proposal","generated_by":"kael-b3-corpus-to-sql"}'::jsonb, true),
  ('plumbing_dirty_water_contact', 'plumbing', 'worker_safety_advisory', 'warning', 'Khi có nước bẩn, nước thải hoặc mùi hôi mạnh, dùng găng tay, hạn chế tiếp xúc trực tiếp và vệ sinh khu vực sau xử lý.', '{"corpus_version":"b3-draft-2026-06-04","signoff_status":"approved","source_refs":["S3"],"source_trust_score":1,"source_trust_scoring":"source_set_minimum_trust_proposal","generated_by":"kael-b3-corpus-to-sql"}'::jsonb, true),
  ('plumbing_floor_protection_evidence', 'plumbing', 'worker_safety_advisory', 'advisory', 'Trước khi đổi phạm vi do thấm sàn, rò tường hoặc phát sinh tháo mở, chụp ảnh bằng chứng và mô tả vị trí rò một cách ngắn gọn.', '{"corpus_version":"b3-draft-2026-06-04","signoff_status":"approved","source_refs":["S3"],"source_trust_score":1,"source_trust_scoring":"source_set_minimum_trust_proposal","generated_by":"kael-b3-corpus-to-sql"}'::jsonb, true),
  ('plumbing_wall_chase_scope_change', 'plumbing', 'worker_safety_advisory', 'warning', 'Nếu cần đục tường, tháo gạch hoặc mở trần, dừng để gửi scope-change kèm lý do và ảnh; không làm trước khi Kael quyết định.', '{"corpus_version":"b3-draft-2026-06-04","signoff_status":"approved","source_refs":["S3"],"source_trust_score":1,"source_trust_scoring":"source_set_minimum_trust_proposal","generated_by":"kael-b3-corpus-to-sql"}'::jsonb, true),
  ('plumbing_shared_riser_boundary', 'plumbing', 'worker_safety_advisory', 'advisory', 'Với ống đứng, van tổng hoặc phần cấp thoát nước chung của tòa nhà, hướng khách phối hợp ban quản lý trước khi thợ can thiệp.', '{"corpus_version":"b3-draft-2026-06-04","signoff_status":"approved","source_refs":["S3"],"source_trust_score":1,"source_trust_scoring":"source_set_minimum_trust_proposal","generated_by":"kael-b3-corpus-to-sql"}'::jsonb, true),
  ('plumbing_post_repair_leak_test', 'plumbing', 'worker_safety_advisory', 'advisory', 'Sau khi thay nối hoặc siết khớp, kiểm tra rò nước tại điểm sửa và báo rõ nếu nghi ngờ ống âm tường cần theo dõi thêm.', '{"corpus_version":"b3-draft-2026-06-04","signoff_status":"approved","source_refs":["S3"],"source_trust_score":1,"source_trust_scoring":"source_set_minimum_trust_proposal","generated_by":"kael-b3-corpus-to-sql"}'::jsonb, true),
  ('plumbing_no_hidden_pipe_guarantee', 'plumbing', 'worker_safety_advisory', 'advisory', 'Không cam kết chắc chắn về ống âm tường hoặc đoạn khuất nếu chưa mở kiểm tra; trình bày phần chưa quan sát được là giới hạn bằng chứng.', '{"corpus_version":"b3-draft-2026-06-04","signoff_status":"approved","source_refs":["S3"],"source_trust_score":1,"source_trust_scoring":"source_set_minimum_trust_proposal","generated_by":"kael-b3-corpus-to-sql"}'::jsonb, true),
