  ('cleaning_bleach_ventilation', 'cleaning', 'worker_safety_advisory', 'warning', 'Khi dùng thuốc tẩy hoặc chất khử khuẩn trong nhà, mở cửa hoặc tăng thông gió để giảm hơi hóa chất trong căn hộ.', '{"corpus_version":"b3-draft-2026-06-04","signoff_status":"approved","source_refs":["S4","S5"],"source_trust_score":0.95,"source_trust_scoring":"source_set_minimum_trust_proposal","generated_by":"kael-b3-corpus-to-sql"}'::jsonb, true),
  ('cleaning_ppe_for_disinfectants', 'cleaning', 'worker_safety_advisory', 'warning', 'Đọc nhãn sản phẩm và dùng găng tay hoặc kính bảo vệ nếu nhãn yêu cầu; tránh để hóa chất bắn vào mắt hoặc da.', '{"corpus_version":"b3-draft-2026-06-04","signoff_status":"approved","source_refs":["S4"],"source_trust_score":0.95,"source_trust_scoring":"source_set_minimum_trust_proposal","generated_by":"kael-b3-corpus-to-sql"}'::jsonb, true),
  ('cleaning_clean_before_disinfect', 'cleaning', 'worker_safety_advisory', 'advisory', 'Làm sạch bụi bẩn bằng nước/xà phòng trước khi khử khuẩn; không xem khử khuẩn là thay thế hoàn toàn cho bước làm sạch.', '{"corpus_version":"b3-draft-2026-06-04","signoff_status":"approved","source_refs":["S4"],"source_trust_score":0.95,"source_trust_scoring":"source_set_minimum_trust_proposal","generated_by":"kael-b3-corpus-to-sql"}'::jsonb, true),
  ('cleaning_sensitive_surface_check', 'cleaning', 'worker_safety_advisory', 'advisory', 'Kiểm tra nhãn và thử ở vùng nhỏ với bề mặt nhạy cảm trước khi dùng hóa chất mạnh để tránh bạc màu hoặc hư hại.', '{"corpus_version":"b3-draft-2026-06-04","signoff_status":"approved","source_refs":["S5"],"source_trust_score":0.95,"source_trust_scoring":"source_set_minimum_trust_proposal","generated_by":"kael-b3-corpus-to-sql"}'::jsonb, true),
  ('cleaning_mold_respiratory_caution', 'cleaning', 'worker_safety_advisory', 'warning', 'Nếu có nấm mốc nhiều hoặc người trong nhà có vấn đề hô hấp, hạn chế khuấy bụi/mốc và khuyến nghị xử lý chuyên nghiệp khi vượt phạm vi dọn thường.', '{"corpus_version":"b3-draft-2026-06-04","signoff_status":"approved","source_refs":["S5"],"source_trust_score":0.95,"source_trust_scoring":"source_set_minimum_trust_proposal","generated_by":"kael-b3-corpus-to-sql"}'::jsonb, true),
  ('cleaning_children_pets_away', 'cleaning', 'worker_safety_advisory', 'warning', 'Giữ trẻ nhỏ, thú cưng và đồ ăn tránh xa khu vực đang dùng hóa chất cho tới khi bề mặt khô và thông gió đủ.', '{"corpus_version":"b3-draft-2026-06-04","signoff_status":"approved","source_refs":["S4","S5"],"source_trust_score":0.95,"source_trust_scoring":"source_set_minimum_trust_proposal","generated_by":"kael-b3-corpus-to-sql"}'::jsonb, true),
  ('cleaning_daily_bleach_solution', 'cleaning', 'worker_safety_advisory', 'advisory', 'Nếu pha dung dịch thuốc tẩy theo nhãn, không lưu dung dịch quá lâu; ưu tiên pha mới theo hướng dẫn sản phẩm.', '{"corpus_version":"b3-draft-2026-06-04","signoff_status":"approved","source_refs":["S4"],"source_trust_score":0.95,"source_trust_scoring":"source_set_minimum_trust_proposal","generated_by":"kael-b3-corpus-to-sql"}'::jsonb, true)
