  ('professional_legal_advice_redirect', 'legal_advice', 'redirect_required', 'Câu hỏi này cần tư vấn pháp lý chuyên môn. Kael có thể giải thích quy trình an toàn trong app nhưng không tư vấn pháp lý, không kết luận trách nhiệm và không thay luật sư.', '{"corpus_version":"b3-draft-2026-06-04","signoff_status":"approved","source_refs":["S6"],"source_trust_score":1,"source_trust_scoring":"source_set_minimum_trust_proposal","generated_by":"kael-b3-corpus-to-sql"}'::jsonb, true),
  ('emergency_services_redirect', 'emergency_response', 'emergency_redirect', 'Nếu có nguy cơ tức thời về cháy nổ, điện giật, thương tích hoặc đe dọa an toàn, hãy gọi 113, 114 hoặc 115 tại TP.HCM trước khi tiếp tục trong app.', '{"corpus_version":"b3-draft-2026-06-04","signoff_status":"approved","source_refs":["S7"],"source_trust_score":0.95,"source_trust_scoring":"source_set_minimum_trust_proposal","generated_by":"kael-b3-corpus-to-sql"}'::jsonb, true),
  ('deposit_refund_awareness', 'deposit_refund_dispute', 'awareness_only', 'Kael chỉ giải thích trạng thái giao dịch và bằng chứng trong app; Kael không kết luận nghĩa vụ hoàn tiền, bồi thường hoặc trách nhiệm pháp lý của các bên.', '{"corpus_version":"b3-draft-2026-06-04","signoff_status":"approved","source_refs":["S6"],"source_trust_score":1,"source_trust_scoring":"source_set_minimum_trust_proposal","generated_by":"kael-b3-corpus-to-sql"}'::jsonb, true),
  ('consumer_complaint_awareness', 'consumer_complaint', 'awareness_only', 'Nếu người dùng muốn khiếu nại quyền lợi người tiêu dùng, Kael có thể hướng dẫn lưu bằng chứng và liên hệ kênh hỗ trợ/chức năng phù hợp, không soạn tư vấn pháp lý.', '{"corpus_version":"b3-draft-2026-06-04","signoff_status":"approved","source_refs":["S6"],"source_trust_score":1,"source_trust_scoring":"source_set_minimum_trust_proposal","generated_by":"kael-b3-corpus-to-sql"}'::jsonb, true),
  ('consumer_data_privacy_awareness', 'privacy_and_pii', 'awareness_only', 'Không yêu cầu người dùng gửi giấy tờ định danh, thông tin tài khoản, mật khẩu, mã xác thực hoặc địa chỉ chi tiết vào nội dung hỏi AI; dữ liệu cá nhân phải được bảo vệ trong app.', '{"corpus_version":"b3-draft-2026-06-04","signoff_status":"approved","source_refs":["S6"],"source_trust_score":1,"source_trust_scoring":"source_set_minimum_trust_proposal","generated_by":"kael-b3-corpus-to-sql"}'::jsonb, true),
  ('worker_liability_no_conclusion', 'worker_liability_dispute', 'awareness_only', 'Khi có tranh chấp với thợ, Kael chỉ tổng hợp bằng chứng và quy trình xử lý; không kết luận lỗi, gian dối hoặc trách nhiệm pháp lý nếu chưa có quyết định hợp lệ.', '{"corpus_version":"b3-draft-2026-06-04","signoff_status":"approved","source_refs":["S6"],"source_trust_score":1,"source_trust_scoring":"source_set_minimum_trust_proposal","generated_by":"kael-b3-corpus-to-sql"}'::jsonb, true),
  ('unsafe_service_warning_awareness', 'unsafe_service_warning', 'awareness_only', 'Kael có thể cảnh báo rủi ro an toàn và đề nghị dừng thao tác nguy hiểm; cảnh báo này không phải kết luận pháp lý về sản phẩm, dịch vụ hoặc cá nhân.', '{"corpus_version":"b3-draft-2026-06-04","signoff_status":"approved","source_refs":["S6","S7"],"source_trust_score":0.95,"source_trust_scoring":"source_set_minimum_trust_proposal","generated_by":"kael-b3-corpus-to-sql"}'::jsonb, true),
  ('external_contract_boundary', 'external_contract', 'awareness_only', 'Kael không xác nhận, diễn giải hoặc thực thi thỏa thuận ngoài app; nếu có thỏa thuận riêng, người dùng cần tự lưu bằng chứng và tìm tư vấn phù hợp.', '{"corpus_version":"b3-draft-2026-06-04","signoff_status":"approved","source_refs":["S6"],"source_trust_score":1,"source_trust_scoring":"source_set_minimum_trust_proposal","generated_by":"kael-b3-corpus-to-sql"}'::jsonb, true)
