update public.service_knowledge_boxes
set safe_metadata = safe_metadata || '{"primary_refs":["S1","S8"],"safety_focus":["electric_shock","thermal_damage","overload","common_area_boundary"],"problem_hints":{"power_outage_one_room":"Check localized outage symptoms, avoid repeated breaker resets, and isolate the affected circuit before inspection.","power_outage_whole_unit":"Treat whole-unit power loss as higher risk; confirm building or common-area boundary before worker intervention.","outlet_or_switch_broken":"Warn about heat, discoloration, water exposure, and stop use before repair.","breaker_trip":"Do not repeatedly reset; inspect overload, short-circuit, or leakage causes.","flickering_light":"Check loose connection or overload signs; escalate on burning smell, sparks, or shock risk.","install_device":"Confirm load, dry mounting, and apartment-only circuit scope before installation.","other_electrical":"Ask for safe symptom details and stop if shock, smoke, fire, or common-area risk appears."},"corpus_version":"b3-draft-2026-06-04","problem_hint_version":"b3-draft-2026-06-04","signoff_status":"approved","source_refs":["S1","S8"],"source_trust_score":0.9,"source_trust_scoring":"source_set_minimum_trust_proposal","generated_by":"kael-b3-corpus-to-sql"}'::jsonb,
